private async Task ValidateFileFields(string filePath, string[] requiredFields,
    List<ValidationIssue> issues)
{
    var json = await _fs.ReadFileAsync(filePath);
    if (json == null) return;

    try
    {
        using var doc = JsonDocument.Parse(json);
        foreach (var field in requiredFields)
        {
            if (!doc.RootElement.TryGetProperty(field, out _))
            {
                issues.Add(new ValidationIssue(
                    $"{filePath}.{field}",
                    IssueSeverity.Error,
                    $"Отсутствует обязательное поле: {field}",
                    code: "missing_required_top_level_field",
                    section: "RequiredFields",
                    expected: field,
                    actual: "missing",
                    repairHint: $"Добавь обязательное поле {field} в canonical файл {filePath}."));
            }
        }
    }
    catch (Exception ex)
    {
        _logger.LogDebug(ex, "Не удалось проверить обязательные поля файла {FilePath}.", filePath);
    }
}

private async Task<WorldTimeResolutionResult> ResolveWorldTimeFromFileAsync(
    int fallback,
    bool allowIncrementalTimeChange = true,
    FileSystemManager.CanonicalWriteLease? writeLease = null)
{
    var json = writeLease == null
        ? await _fs.ReadFileAsync("game_state/world/world_time.json")
        : await _fs.ReadFileAsync(
            writeLease,
            "game_state/world/world_time.json");
    if (string.IsNullOrWhiteSpace(json))
        return new WorldTimeResolutionResult(fallback, true);

    try
    {
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;

        if (TryReadIntLike(root, "currentTimeInMinutes", out var absolute))
            return new WorldTimeResolutionResult(absolute, false);

        if (root.TryGetProperty("setWorldTime", out var setWorldTime) &&
            setWorldTime.ValueKind == JsonValueKind.Object)
        {
            if (TryReadIntLike(setWorldTime, "currentTimeInMinutes", out absolute))
                return new WorldTimeResolutionResult(absolute, false);

            if (LooksLikeAbsoluteWorldTimeObject(setWorldTime))
                return new WorldTimeResolutionResult(fallback, true);
        }

        if (allowIncrementalTimeChange && TryReadIntLike(root, "timeChange", out var delta))
            return new WorldTimeResolutionResult(Math.Max(0, fallback + delta), false);

        if (LooksLikeAbsoluteWorldTimeObject(root))
            return new WorldTimeResolutionResult(fallback, true);
    }
    catch (Exception ex)
    {
        _logger.LogDebug(ex, "Не удалось прочитать world_time.json для progression scheduler");
        return new WorldTimeResolutionResult(fallback, true);
    }

    return new WorldTimeResolutionResult(fallback, true);
}
